cat /app/app/mailers/application_mailer.rb && cat <<'EOF' > /app/app/mailers/user_mailer.rb
require "uri"

class UserMailer < ApplicationMailer
  def email_verification(user, raw_token)
    @user = user
    @account = user.account
    @verification_url = frontend_link("/verify-email", account: @account.subdomain, token: raw_token)

    mail(
      to: @user.email,
      subject: "Verify your email for #{@account.name}"
    )
  end

  def password_reset(user, raw_token)
    @user = user
    @account = user.account
    @reset_url = frontend_link("/reset-password", account: @account.subdomain, token: raw_token)

    mail(
      to: @user.email,
      subject: "Reset your password for #{@account.name}"
    )
  end

  def invitation(invitation, raw_token)
    @invitation = invitation
    @account = invitation.account
    @accept_url = frontend_link("/accept-invitation", account: @account.subdomain, token: raw_token)

    mail(
      to: @invitation.email,
      subject: "You've been invited to join #{@account.name}"
    )
  end

  private

  def frontend_link(path, params)
    base_url = ENV.fetch("HELPDESK_FRONTEND_URL", "http://localhost:3001").strip.sub(%r{/+\z}, "")
    "#{base_url}#{path}?#{URI.encode_www_form(params)}"
  end
end
EOF

