<p>Hi,</p>

<p>You have been invited to join <%= @account.name %> as <%= @invitation.role == "admin" ? "an admin" : "an agent" %>.</p>

<p>Click the link below to accept your invitation:</p>

<p><a href="<%= @accept_url %>"><%= @accept_url %></a></p>
EOF

